@if($rows->isNotEmpty())<ul class="analytics-watchlist">@foreach($rows as $row)<li><span class="event-member-initials">{{ collect(explode(' ', $row['user']->name))->map(fn($part) => mb_substr($part, 0, 1))->take(2)->join('') }}</span><div><a href="{{ route('users.show', $row['user']) }}" wire:navigate>{{ $row['user']->name }}</a><small>{{ $row['user']->smallGroups->pluck('name')->join(', ') ?: 'No active cell group' }}</small><p>@if($row['lowScore'])<span>Score {{ $row['score'] }}</span>@endif @if($row['lowRate'])<span>{{ $row['rate'] }}% in {{ $row['recentTotal'] }} recent events</span>@endif</p></div><div class="analytics-contact">@if($row['user']->phone)<a href="tel:{{ $row['user']->phone }}" title="Call {{ $row['user']->name }}"><x-heroicon-o-phone /></a>@endif<a href="mailto:{{ $row['user']->email }}" title="Email {{ $row['user']->name }}"><x-heroicon-o-envelope /></a></div></li>@endforeach</ul>@else<div class="event-empty-state event-empty-compact"><h3>No members need attention</h3><p>No visible member currently meets the watchlist rules.</p></div>@endif
